files.content:
.cpr-container {
  position: relative;
  width: 100%;
  height: 100svh;
  overflow: hidden;
}

.cpr-hero {
  position: relative;
  width: 100%;
  height: 100svh;
  padding: 1rem;
  background-color: var(--cpr-bg, #181717);
}

.cpr-hero-inner {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 4rem;
  overflow: hidden;
}

.cpr-hero-img {
  position: absolute;
  width: 100%;
  height: 100%;
  transform: scale(1.5);
  will-change: transform;
}

.cpr-hero-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cpr-hero-content {
  position: absolute;
  width: 100%;
  height: 100%;
  padding: 2rem;
  color: var(--cpr-fg, #f5f5f5);
}

.cpr-header h1 {
  font-size: 12rem;
  font-weight: 500;
  letter-spacing: -0.25rem;
  line-height: 1;
}

.cpr-hero-footer {
  position: absolute;
  bottom: 0;
  left: 0;
  padding: 2rem;
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
}

.cpr-hero-footer h3 {
  font-size: 2rem;
  font-weight: 400;
  line-height: 1.1;
  width: 25%;
}

.cpr-hero-footer p {
  width: 25%;
  text-align: right;
  opacity: 0.5;
}

/* Preloader layers */
.cpr-preloader-progress,
.cpr-preloader-mask,
.cpr-preloader-content {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100svh;
  pointer-events: none;
}

.cpr-preloader-progress {
  background-color: var(--cpr-preloader-bg, #292725);
  z-index: 1;
  will-change: opacity;
}

.cpr-progress-bar {
  position: absolute;
  top: 0;
  left: 50%;
  width: 55%;
  height: 100%;
  background-color: var(--cpr-fg, #f5f5f5);
  transform: translateX(-50%) scaleX(0);
  will-change: transform;
  transform-origin: left;
}

.cpr-preloader-logo {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 100%;
  text-align: center;
  mix-blend-mode: difference;
  z-index: 2;
}

.cpr-preloader-logo h1 {
  position: relative;
  color: var(--cpr-fg, #f5f5f5);
  font-size: 3rem;
  font-weight: 500;
  line-height: 1;
}

.cpr-preloader-mask {
  background-color: var(--cpr-bg, #181717);
  mask:
    linear-gradient(#fff, #fff),
    radial-gradient(circle at 50% 50%, #fff 25%, transparent 25.5%);
  -webkit-mask:
    linear-gradient(#fff, #fff),
    radial-gradient(circle at 50% 50%, #fff 25%, transparent 25.5%);
  mask-composite: subtract;
  -webkit-mask-composite: xor;
  will-change: transform;
  z-index: 1;
}

.cpr-preloader-content {
  z-index: 2;
}

.cpr-preloader-footer {
  position: absolute;
  bottom: 4rem;
  left: 50%;
  transform: translate(-50%);
  width: 30%;
  text-align: center;
}

.cpr-preloader-footer p {
  color: var(--cpr-fg, #f5f5f5);
  opacity: 0.5;
}

.cpr-char,
.cpr-line {
  position: relative;
  padding-bottom: 0.2em;
  margin-bottom: -0.2em;
  will-change: transform;
}

@media (max-width: 800px) {
  .cpr-hero-inner {
    border-radius: 3rem;
  }

  .cpr-header h1 {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    width: 100%;
    font-size: 4rem;
    letter-spacing: 0;
  }

  .cpr-hero-footer {
    flex-direction: column;
    gap: 0.5rem;
    align-items: flex-start;
  }

  .cpr-hero-footer h3,
  .cpr-hero-footer p {
    width: 100%;
    text-align: left;
  }

  .cpr-hero-footer h3 {
    font-size: 1.25rem;
  }

  .cpr-progress-bar {
    left: 0;
    width: 100%;
    transform: translateX(0) scaleX(0);
  }

  .cpr-preloader-logo h1 {
    font-size: 2rem;
  }

  .cpr-preloader-mask {
    mask:
      linear-gradient(#fff, #fff),
      radial-gradient(circle at 50% 50%, #fff 45%, transparent 45.5%);
    -webkit-mask:
      linear-gradient(#fff, #fff),
      radial-gradient(circle at 50% 50%, #fff 45%, transparent 45.5%);
    mask-composite: subtract;
    -webkit-mask-composite: xor;
  }

  .cpr-preloader-footer {
    width: 75%;
  }
}
